83	void update_grid(void)
84	{
85	  uint32_t gdigit = 100000000;
86	  uint32_t fstart = get_sweep_frequency(ST_START);
87	  uint32_t fspan  = get_sweep_frequency(ST_SPAN);
88	  uint32_t grid;
89	
90	  while (gdigit > 100) {
91	    grid = 5 * gdigit;
92	    if (fspan / grid >= 4)
93	      break;
94	    grid = 2 * gdigit;
95	    if (fspan / grid >= 4)
96	      break;
97	    grid = gdigit;
98	    if (fspan / grid >= 4)
99	      break;
100	    gdigit /= 10;
101	  }
102	
103	  grid_offset = (WIDTH) * ((fstart % grid) / 100) / (fspan / 100);
104	  grid_width = (WIDTH) * (grid / 100) / (fspan / 1000);
105	
106	  force_set_markmap();
107	  redraw_request |= REDRAW_FREQUENCY;
108	}
