110	static inline int
111	circle_inout(int x, int y, int r)
112	{
113	  int d = x*x + y*y - r*r;
114	  if (d < -r)
115	    return 1;
116	  if (d >  r)
117	    return -1;
118	  return 0;
119	}
120	
121	static int
122	polar_grid(int x, int y)
123	{
124	  int d;
125	
126	  // offset to center
127	  x -= P_CENTER_X;
128	  y -= P_CENTER_Y;
129	
130	  // outer circle
131	  d = circle_inout(x, y, P_RADIUS);
132	  if (d < 0) return 0;
133	  if (d == 0) return 1;
134	
135	  // vertical and horizontal axis
136	  if (x == 0 || y == 0) return 1;
137	
138	  d = circle_inout(x, y, P_RADIUS / 5);
139	  if (d == 0) return 1;
140	  if (d > 0) return 0;
141	
142	  d = circle_inout(x, y, P_RADIUS * 2 / 5);
143	  if (d == 0) return 1;
144	  if (d > 0) return 0;
145	
146	  // cross sloping lines
147	  if (x == y || x == -y) return 1;
148	
149	  d = circle_inout(x, y, P_RADIUS * 3 / 5);
150	  if (d == 0) return 1;
151	  if (d > 0) return 0;
152	
153	  d = circle_inout(x, y, P_RADIUS * 4 / 5);
154	  if (d == 0) return 1;
155	  return 0;
156	}
157	
158	/*
159	 * Constant Resistance circle: (u - r/(r+1))^2 + v^2 = 1/(r+1)^2
160	 * Constant Reactance circle:  (u - 1)^2 + (v-1/x)^2 = 1/x^2
161	 */
162	static int
163	smith_grid(int x, int y)
164	{
165	  int d;
166	
167	  // offset to center
168	  x -= P_CENTER_X;
169	  y -= P_CENTER_Y;
170	
171	  // outer circle
172	  d = circle_inout(x, y, P_RADIUS);
173	  if (d < 0) return 0;
174	  if (d == 0) return 1;
175	
176	  // horizontal axis
177	  if (y == 0) return 1;
178	
179	  // shift circle center to right origin
180	  x -= P_RADIUS;
181	
182	  // Constant Reactance Circle: 2j : R/2 = P_RADIUS/2
183	  if (circle_inout(x, y + P_RADIUS / 2, P_RADIUS / 2) == 0) return 1;
184	  if (circle_inout(x, y - P_RADIUS / 2, P_RADIUS / 2) == 0) return 1;
185	
186	  // Constant Resistance Circle: 3 : R/4 = P_RADIUS/4
187	  d = circle_inout(x + P_RADIUS / 4, y, P_RADIUS / 4);
188	  if (d > 0) return 0;
189	  if (d == 0) return 1;
190	
191	  // Constant Reactance Circle: 1j : R = P_RADIUS
192	  if (circle_inout(x, y + P_RADIUS, P_RADIUS) == 0) return 1;
193	  if (circle_inout(x, y - P_RADIUS, P_RADIUS) == 0) return 1;
194	
195	  // Constant Resistance Circle: 1 : R/2
196	  d = circle_inout(x + P_RADIUS / 2, y, P_RADIUS / 2);
197	  if (d > 0) return 0;
198	  if (d == 0) return 1;
199	
200	  // Constant Reactance Circle: 1/2j : R*2
201	  if (circle_inout(x, y + P_RADIUS * 2, P_RADIUS * 2) == 0) return 1;
202	  if (circle_inout(x, y - P_RADIUS * 2, P_RADIUS * 2) == 0) return 1;
203	
204	  // Constant Resistance Circle: 1/3 : R*3/4
205	  if (circle_inout(x + P_RADIUS * 3 / 4, y, P_RADIUS * 3 / 4) == 0) return 1;
206	  return 0;
207	}
