455	/*
456	 * calculate abs(gamma)
457	 */
458	static float
459	linear(const float *v)
460	{
461	  return - sqrtf(v[0]*v[0] + v[1]*v[1]);
462	}
463	
464	/*
465	 * calculate vswr; (1+gamma)/(1-gamma)
466	 */ 
467	static float
468	swr(const float *v)
469	{
470	  float x = sqrtf(v[0]*v[0] + v[1]*v[1]);
471	  if (x >= 1)
472	    return INFINITY;
473	  return (1 + x)/(1 - x);
474	}
