476	static float
477	resitance(const float *v)
478	{
479	  float z0 = 50;
480	  float d = z0 / ((1-v[0])*(1-v[0])+v[1]*v[1]);
481	  float zr = ((1+v[0])*(1-v[0]) - v[1]*v[1]) * d;
482	  return zr;
483	}
484	
485	static float
486	reactance(const float *v)
487	{
488	  float z0 = 50;
489	  float d = z0 / ((1-v[0])*(1-v[0])+v[1]*v[1]);
490	  float zi = 2*v[1] * d;
491	  return zi;
492	}
493	
494	static float
495	qualityfactor(const float *v)
496	{
497	  float i = 2*v[1];
498	  float r = (1+v[0])*(1-v[0]) - v[1]*v[1];
499	  return fabs(i / r);
500	}
