516	float
517	groupdelay_from_array(int i, float array[POINTS_COUNT][2])
518	{
519	  int bottom = (i ==   0) ?   0 : i - 1;
520	  int top    = (i == sweep_points-1) ? sweep_points-1 : i + 1;
521	  float deltaf = frequencies[top] - frequencies[bottom];
522	  return groupdelay(array[bottom], array[top], deltaf);
523	}
