836	static void
837	mark_cells_from_index(void)
838	{
839	  int t, i, j;
840	  /* mark cells between each neighber points */
841	  map_t *map = &markmap[current_mappage][0];
842	  for (t = 0; t < TRACES_MAX; t++) {
843	    if (!trace[t].enabled)
844	      continue;
845	    index_t *index = &trace_index[t][0];
846	    int m0 = CELL_X(index[0]) / CELLWIDTH;
847	    int n0 = CELL_Y(index[0]) / CELLHEIGHT;
848	    map[n0] |= 1 << m0;
849	    for (i = 1; i < sweep_points; i++) {
850	      int m1 = CELL_X(index[i]) / CELLWIDTH;
851	      int n1 = CELL_Y(index[i]) / CELLHEIGHT;
852	      if (m0 == m1 && n0 == n1)
853	        continue;
854	      int x0 = m0; int x1 = m1; if (x0>x1) SWAP(x0, x1); m0 = m1;
855	      int y0 = n0; int y1 = n1; if (y0>y1) SWAP(y0, y1); n0 = n1;
856	      for (; y0 <= y1; y0++)
857	        for (j = x0; j <= x1; j++)
858	          map[y0] |= 1 << j;
859	    }
860	  }
861	}
