901	search_index_range_x(int x1, int x2, index_t index[POINTS_COUNT], int *i0, int *i1)
902	{
903	  int i, j;
904	  int head = 0;
905	  int tail = sweep_points;
906	  int idx_x;
907	
908	  // Search index point in cell
909	  while (1) {
910	    i = (head + tail) / 2;
911	    idx_x = CELL_X(index[i]);
912	    if (idx_x >= x2) { // index after cell
913	      if (tail == i)
914	        return false;
915	      tail = i;
916	    }
917	    else if (idx_x < x1) {    // index before cell
918	      if (head == i)
919	        return false;
920	      head = i;
921	    }
922	    else  // index in cell (x =< idx_x < cell_end)
923	      break;
924	  }
925	  j = i;
926	  // Search index left from point
927	  do {
928	    j--;
929	  } while (j > 0 && x1 <= CELL_X(index[j]));
930	  *i0 = j;
931	  // Search index right from point
932	  do {
933	    i++;
934	  } while (i < sweep_points-1 && CELL_X(index[i]) < x2);
935	  *i1 = i;
936	
937	  return TRUE;
938	}
