static void
draw_refpos(int x, int y, int c)
{
  int y0 = y, j;
  for (j = 0; j < REFERENCE_HEIGHT; j++, y0++) {
    if (y0 < 0 || y0 >= CELLHEIGHT) continue;
    int x0 = x;
    uint8_t bits = reference_bitmap[j];
    while (bits) {
      if (x0 >= 0 && x0 < CELLWIDTH)
        cell_buffer[y0 * CELLWIDTH + x0] = (bits & 0x80) ? c : DEFAULT_BG_COLOR;
      x0++;
      bits <<= 1;
    }
  }
}

